    public static function normalize(string $language): string
    {
        $language = strtolower($language);

        return match ($language) {
            'php', 'php8' => 'php',
            'js', 'javascript', 'mjs', 'cjs' => 'js',
            'jsx' => 'jsx',
            'ts', 'typescript', 'mts' => 'ts',
            'tsx' => 'tsx',
            'json', 'jsonc' => 'json',
            'bash', 'sh', 'shell', 'zsh' => 'bash',
            'yaml', 'yml' => 'yaml',
            'css', 'scss' => 'css',
            'html', 'htm' => 'html',
            'blade', 'laravel' => 'blade',
            'py', 'python' => 'python',
            'vue' => 'vue',
            'rs', 'rust' => 'rust',
            'sql' => 'sql',
            'c' => 'c',
            'cpp', 'c++', 'cxx', 'cc' => 'cpp',
            'md', 'markdown' => 'md',
            default => $language === '' ? 'txt' : $language,
        };
    }
